class MapPointsManager {
  static FLAG_NAME = "mapPointGroups";

  /**
   * Retrieves all map point groups from the current scene.
   * @returns {object} The object containing all point groups, or an empty object if none exist.
   */
  static getGroups() {
    if (!canvas.scene?.id) {
      // This is a genuine error state we should still check for.
      console.error(
        "MapShine | FATAL: MapPointsManager.getGroups() was called but canvas.scene is not fully available."
      );
      return {};
    }

    // This call might return 'undefined' on initial load before flags are ready.
    const groupsData = canvas.scene.getFlag(MODULE_ID, this.FLAG_NAME);

    // Debug: Log the raw groups data to detect duplicates or corruption
    if (groupsData) {
      const groupIds = Object.keys(groupsData);
      // console.log(`MapShine | getGroups() returning ${groupIds.length} groups:`, groupIds.map(id => {
      //   const g = groupsData[id];
      //   return `[${id}] ${g.label} (${g.points?.length ?? 0} pts)`;
      // }).join(', '));
    }

    // Return the data if it exists, otherwise return an empty object.
    // This prevents the system from crashing if the data isn't ready yet.
    return groupsData ?? {};
  }

  /**
   * Retrieves a single map point group by its ID.
   * @param {string} groupId The ID of the group to retrieve.
   * @returns {object|undefined} The group object, or undefined if not found.
   */
  static getGroup(groupId) {
    const groups = this.getGroups();
    return groups[groupId];
  }

  /**
   * Creates a new group and stores it in the scene's flags.
   * @param {Object} options
   * @param {string} [options.label="New Group"] The label for the group.
   * @param {string} [options.type="point"] The type of group ('point', 'line', 'area').
   * @param {Object} [options.ropeSettings] Optional rope-specific settings to apply immediately
   * @returns {Promise<string>} The ID of the newly created group.
   */
  static async createGroup({
    label = "New Group",
    type = "point",
    ropeSettings = null,
  } = {}) {
    if (!game.user.isGM) {
      ui.notifications.warn(
        "You do not have permission to create map point groups."
      );
      return null;
    }
    const groupId = foundry.utils.randomID();
    const newGroup = {
      id: groupId,
      label: label,
      type: type,
      points: [],
      isBroken: false,
      reason: "",
      isEffectSource: false,
      effectTarget: "",
      emission: {
        intensity: 1.0,
        falloff: {
          enabled: false,
          strength: 0.5,
        },
      },
    };

    if (type === "rope") {
      // If rope settings are provided, use them; otherwise, construct defaults for the 'rope' type.
      if (ropeSettings) {
        Object.assign(newGroup, ropeSettings);
      } else {
        // Fallback to the 'rope' type defaults, as this is the generic option in the Map Points Editor.
        const ropeType = "rope";
        const preset = ROPE_TYPE_PRESETS[ropeType];
        const profileConfig =
          game.mapShine.profileManager.activeConfig.physicsRope[ropeType] || {};

        newGroup.ropeType = ropeType;
        newGroup.texturePath = profileConfig.texturePath || preset.texturePath;
        newGroup.segmentLength =
          profileConfig.segmentLength ?? preset.segmentLength;
        newGroup.animationSpeed =
          profileConfig.animationSpeed ?? preset.animationSpeed;
        newGroup.damping = profileConfig.damping ?? preset.damping;
        newGroup.windForce = profileConfig.windForce ?? preset.windForce;
        newGroup.tapering = profileConfig.tapering ?? preset.tapering;
        newGroup.indoorWindShielding =
          profileConfig.indoorWindShielding ?? preset.indoorWindShielding;
        newGroup.endpointFade =
          profileConfig.endpointFade ?? preset.endpointFade;
        newGroup.fadeStartDistance =
          profileConfig.fadeStartDistance ?? preset.fadeStartDistance;
        newGroup.fadeEndDistance =
          profileConfig.fadeEndDistance ?? preset.fadeEndDistance;
      }
      newGroup.isIndoors = newGroup.isIndoors ?? false; // Default to outdoor (full wind)
    }

    const path = `flags.${MODULE_ID}.${this.FLAG_NAME}.${groupId}`;
    await canvas.scene.update({
      [path]: newGroup,
    });
    // @ts-expect-error - Custom hook type augmentation not working with foundry-vtt-types package
    Hooks.callAll("mapShine:mapPointsUpdated", {
      created: groupId,
    });
    return groupId;
  }

  static async updateGroupProperties(groupId, properties) {
    if (!game.user.isGM) return; // No warning needed for rapid changes.

    const group = this.getGroup(groupId);
    if (!group) {
      console.warn(
        `MapPointsManager | Cannot update properties for non-existent group "${groupId}".`
      );
      return;
    }

    const updateData = {};
    for (const [key, value] of Object.entries(properties)) {
      updateData[`flags.${MODULE_ID}.${this.FLAG_NAME}.${groupId}.${key}`] =
        value;
    }

    if (!foundry.utils.isEmpty(updateData)) {
      await canvas.scene.update(updateData, {
        diff: false,
      });
      // @ts-expect-error - Custom hook type augmentation not working with foundry-vtt-types package
      Hooks.callAll("mapShine:mapPointsUpdated", {
        updated: groupId,
      });
    }
  }

  static async deleteGroup(groupId) {
    if (!game.user.isGM) {
      ui.notifications.warn(
        "You do not have permission to delete map point groups."
      );
      return;
    }

    console.log(
      `MapShine | MapPointsManager: Attempting to delete group "${groupId}"`
    );
    const path = `flags.${MODULE_ID}.${this.FLAG_NAME}.-=${groupId}`;
    console.log(
      `MapShine | MapPointsManager: Deleting group with path "${path}"`
    );
    await canvas.scene.update({
      [path]: null,
    });
    console.log(
      `MapShine | MapPointsManager: Group "${groupId}" deleted successfully.`
    );

    // If the deleted group was the active one, clear it
    if (game.mapShine.activeMapPointGroup === groupId) {
      game.mapShine.activeMapPointGroup = null;
    }
    // @ts-expect-error - Custom hook type augmentation not working with foundry-vtt-types package
    Hooks.callAll("mapShine:mapPointsUpdated", {
      deleted: groupId,
    });
  }

  static async addPoint(groupId, point) {
    if (!game.user.isGM) return; // No warning needed for rapid changes like adding points.

    console.log(
      `MapShine | MapPointsManager: Attempting to add point to group "${groupId}".`,
      point
    );
    const group = this.getGroup(groupId);
    if (!group) {
      console.warn(
        `MapPointsManager | Cannot add point to non-existent group "${groupId}".`
      );
      return;
    }

    const newPoints = [...group.points, point];
    const updatedGroup = this.validate({
      ...group,
      points: newPoints,
    });

    const path = `flags.${MODULE_ID}.${this.FLAG_NAME}.${groupId}`;
    console.log(
      `MapShine | MapPointsManager: Updating scene with path "${path}".`
    );
    await canvas.scene.update({
      [path]: updatedGroup,
    });
    console.log(
      `MapShine | MapPointsManager: Scene update complete. Calling hook.`
    );
    // @ts-expect-error - Custom hook type augmentation not working with foundry-vtt-types package
    Hooks.callAll("mapShine:mapPointsUpdated", {
      updated: groupId,
    });
  }

  static async updatePoint(groupId, pointIndex, newPosition) {
    if (!game.user.isGM) return; // No warning needed for rapid changes.

    const group = this.getGroup(groupId);
    if (!group || !group.points[pointIndex]) {
      console.warn(
        `MapPointsManager | Cannot update point at index ${pointIndex} in non-existent group "${groupId}".`
      );
      return;
    }

    const newPoints = [...group.points];
    newPoints[pointIndex] = newPosition;
    const updatedGroup = this.validate({
      ...group,
      points: newPoints,
    });

    const path = `flags.${MODULE_ID}.${this.FLAG_NAME}.${groupId}`;
    await canvas.scene.update({
      [path]: updatedGroup,
    });
    Hooks.callAll("mapShine:mapPointsUpdated", {
      updated: groupId,
    });
  }

  static async removePoint(groupId, pointIndex) {
    if (!game.user.isGM) return; // No warning.

    const group = this.getGroup(groupId);
    if (!group) return;
    const newPoints = [...group.points];
    newPoints.splice(pointIndex, 1);
    const updatedGroup = this.validate({
      ...group,
      points: newPoints,
    });

    const path = `flags.${MODULE_ID}.${this.FLAG_NAME}.${groupId}`;
    await canvas.scene.update({
      [path]: updatedGroup,
    });
    Hooks.callAll("mapShine:mapPointsUpdated", {
      updated: groupId,
    });
  }

  /**
   * Validates a group, primarily checking for self-intersections in polygons.
   * @param {object} group The group object to validate.
   * @returns {object} The group object with updated 'isBroken' and 'reason' fields.
   */
  static validate(group) {
    if (group.type !== "area" || group.points.length < 4) {
      group.isBroken = false;
      group.reason = "";
      console.log(
        `MapShine | Validate: Group "${group.label}" (${group.type}, ${group.points.length} pts) → isBroken = false (< 4 points)`
      );
      return group;
    }

    const points = group.points;
    for (let i = 0; i < points.length; i++) {
      const p1 = points[i];
      const p2 = points[(i + 1) % points.length]; // Next point, wraps around

      // Check against all non-adjacent segments
      for (let j = i + 2; j < points.length; j++) {
        // Skip the segment that connects back to the start
        if (i === 0 && j === points.length - 1) continue;

        const p3 = points[j];
        const p4 = points[(j + 1) % points.length];

        if (this._checkIntersection(p1, p2, p3, p4)) {
          group.isBroken = true;
          group.reason = `Segment ${i + 1}-${i + 2} intersects segment ${
            j + 1
          }-${j + 2}.`;
          console.log(
            `MapShine | Validate: Group "${group.label}" (${group.type}, ${group.points.length} pts) → isBroken = true (${group.reason})`
          );
          return group;
        }
      }
    }

    group.isBroken = false;
    group.reason = "";
    console.log(
      `MapShine | Validate: Group "${group.label}" (${group.type}, ${group.points.length} pts) → isBroken = false (no intersections)`
    );
    return group;
  }

  /**
   * Checks if two line segments intersect.
   * @param {{x,y}} p1 - Start of line 1
   * @param {{x,y}} p2 - End of line 1
   * @param {{x,y}} p3 - Start of line 2
   * @param {{x,y}} p4 - End of line 2
   * @returns {boolean} True if they intersect, false otherwise.
   */
  static _checkIntersection(p1, p2, p3, p4) {
    const den = (p1.x - p2.x) * (p3.y - p4.y) - (p1.y - p2.y) * (p3.x - p4.x);
    if (den === 0) return false; // Parallel or collinear

    const t =
      ((p1.x - p3.x) * (p3.y - p4.y) - (p1.y - p3.y) * (p3.x - p4.x)) / den;
    const u =
      -((p1.x - p2.x) * (p1.y - p3.y) - (p1.y - p2.y) * (p1.x - p3.x)) / den;

    return t > 0 && t < 1 && u > 0 && u < 1;
  }
}

class GeometryMaskManager {
  constructor() {
    this.renderer = canvas.app?.renderer;
    this.masks = new Map(); // Key: effectTarget, Value: { texture: PIXI.RenderTexture, graphics: PIXI.Graphics }
    this._needsUpdate = true;
    this._destroyed = false;
    this._mapPointsInitialized = false; // Flag to ensure the initial point discovery runs only once.
    this._changedGroupId = null; // Track which group changed to enable targeted emitter rebuild

    this._boundOnMapPointsUpdated = this._onMapPointsUpdated.bind(this);
    this._boundOnPan = this.requestUpdate.bind(this);
    this._boundOnResize = this._onResize.bind(this);
  }

  initialize() {
    if (!this.renderer) {
      console.error(
        "GeometryMaskManager | Cannot initialize without a renderer."
      );
      return;
    }

    // Reset the flag for each new scene to allow the initialization poll to run again.
    this._mapPointsInitialized = false;

    // Do NOT create any textures here. They will be created on-demand.

    Hooks.on("mapShine:mapPointsUpdated", this._boundOnMapPointsUpdated);
    Hooks.on("canvasPan", this._boundOnPan);
    window.addEventListener("resize", this._boundOnResize);

    this.requestUpdate();
    console.log(
      `Map Shine | GeometryMaskManager initialized (Lazy Texture Allocation).`
    );
  }

  destroy() {
    if (this._destroyed) return;
    this._destroyed = true;

    Hooks.off("mapShine:mapPointsUpdated", this._boundOnMapPointsUpdated);
    Hooks.off("canvasPan", this._boundOnPan);
    window.removeEventListener("resize", this._boundOnResize);

    for (const { texture, graphics } of this.masks.values()) {
      texture.destroy(true);
      graphics.destroy();
    }
    this.masks.clear();
    console.log("Map Shine | GeometryMaskManager destroyed.");
  }

  /**
   * Ensures a mask texture and graphics object exist for a given effect key.
   * Creates them on-demand if they do not.
   * @param {string} effectKey The effect identifier (e.g., 'sparks').
   * @private
   */
  _ensureMaskExists(effectKey) {
    if (!this.masks.has(effectKey)) {
      const screen = CoordinateManager.getScreenDimensions();
      const renderTexture = PIXI.RenderTexture.create({
        width: screen.width,
        height: screen.height,
      });
      const graphics = new PIXI.Graphics();

      this.masks.set(effectKey, {
        texture: renderTexture,
        graphics,
      });
    }
  }

  /**
   * Handler for map points updated hook. Captures which group changed for targeted emitter rebuild.
   */
  _onMapPointsUpdated(data) {
    // Store which group changed (created, updated, or deleted)
    this._changedGroupId =
      data?.created || data?.updated || data?.deleted || null;
    this.requestUpdate();
  }

  /**
   * Flags that the masks need to be re-rendered on the next animation frame.
   * This is the single, consolidated entry point for requesting an update.
   */
  requestUpdate() {
    this._needsUpdate = true;
  }

  _onResize() {
    if (!this.renderer) return;
    const screen = CoordinateManager.getScreenDimensions();
    // Only resize textures that have already been created.
    for (const { texture } of this.masks.values()) {
      texture.resize(screen.width, screen.height);
    }
    this.requestUpdate();
  }

  /**
   * This method is called by the main animation loop (ParticleLayer._onAnimate).
   * It is the single source of truth for deciding when to render masks and notify other systems.
   */
  update() {
    // --- ROBUST INITIALIZATION POLLING ---
    // This block handles the initial discovery of map points when a scene loads.
    if (!this._mapPointsInitialized) {
      const groupsData = canvas.scene.getFlag(
        MODULE_ID,
        MapPointsManager.FLAG_NAME
      );
      if (groupsData !== undefined) {
        this._mapPointsInitialized = true;
        // If groups exist on first load, flag an update to render them.
        if (!foundry.utils.isEmpty(groupsData)) {
          this._needsUpdate = true;
        }
      }
    }
    // --- END POLLING ---

    // If no update has been requested and the manager is not destroyed, do nothing.
    if (!this._needsUpdate || this._destroyed) return;

    // Perform the render.
    this._renderAllMasks();
    // Reset the flag so we don't re-render unnecessarily on the next frame.
    this._needsUpdate = false;

    // Defer the notification to the next animation frame.
    // This ensures the GPU has processed the render command before other systems try to use the texture.
    const changedGroupId = this._changedGroupId;
    this._changedGroupId = null; // Clear after capturing
    requestAnimationFrame(() => {
      if (this._destroyed) return;
      // console.log(
      //   "Map Shine | GeometryMaskManager: Masks rendered, notifying particle systems.",
      //   changedGroupId ? `Changed group: ${changedGroupId}` : "(no specific group)"
      // );
      // @ts-expect-error - Custom hook type augmentation not working with foundry-vtt-types package
      Hooks.callAll("mapShine:masksRendered", { changedGroupId });
    });
  }

  _renderAllMasks() {
    // console.log("Map Shine | GeometryMaskManager: Rendering all masks...");
    // Clear all existing graphics objects first
    for (const { graphics } of this.masks.values()) {
      graphics.clear();
    }

    const groups = MapPointsManager.getGroups();
    if (foundry.utils.isEmpty(groups)) {
      // console.log(
      //   "Map Shine | GeometryMaskManager: No groups found, skipping render."
      // );
      return;
    }

    // Populate graphics objects based on point groups
    let renderedCount = 0;
    for (const group of Object.values(groups)) {
      if (!group.isEffectSource || !group.effectTarget) {
        continue;
      }

      // LAZY INSTANTIATION: Ensure mask exists for this effect before drawing
      this._ensureMaskExists(group.effectTarget);

      const { graphics } = this.masks.get(group.effectTarget);
      const pointRadius = 16; // World-space radius for point sources
      const lineThickness = 24; // World-space thickness for line sources

      switch (group.type) {
        case "point":
          graphics.beginFill(0xffffff);
          for (const p of group.points) {
            graphics.drawCircle(p.x, p.y, pointRadius);
          }
          graphics.endFill();
          break;
        case "line":
          graphics.lineStyle({
            width: lineThickness,
            color: 0xffffff,
            cap: PIXI.LINE_CAP.ROUND,
          });
          if (group.points.length > 0) {
            graphics.moveTo(group.points[0].x, group.points[0].y);
            for (let i = 1; i < group.points.length; i++) {
              graphics.lineTo(group.points[i].x, group.points[i].y);
            }
          }
          graphics.lineStyle({
            width: 0,
          }); // Reset line style
          break;
        case "area":
          if (group.points.length > 2 && !group.isBroken) {
            // console.log(
            //   `Map Shine | GeometryMaskManager: Rendering area "${group.label}" → ${group.effectTarget} (${group.points.length} pts, broken: ${group.isBroken})`
            // );
            graphics.beginFill(0xffffff);
            graphics.drawPolygon(group.points);
            graphics.endFill();
            renderedCount++;
          } else {
            // console.log(
            //   `Map Shine | GeometryMaskManager: Skipping area "${group.label}" (${group.points.length} pts, broken: ${group.isBroken})`
            // );
          }
          break;
      }
    }

    // Render each graphics object to its texture
    for (const { graphics, texture } of this.masks.values()) {
      const renderContainer = new PIXI.Container();
      renderContainer.addChild(graphics);

      // Apply the world-to-screen transformation directly to the container.
      renderContainer.transform.setFromMatrix(
        canvas.stage.transform.worldTransform
      );

      // Render the pre-transformed container.
      this.renderer.render(renderContainer, {
        renderTexture: texture,
        clear: true,
      });

      // Clean up the temporary container.
      renderContainer.removeChild(graphics);
      renderContainer.destroy();
    }
    // console.log(
    //   `Map Shine | GeometryMaskManager: Rendered ${renderedCount} effect groups to masks.`
    // );
  }

  /**
   * Retrieves a generated mask for a specific effect.
   * Creates the texture on-demand if it doesn't exist.
   * @param {string} effectKey The key of the effect (e.g., 'sparks').
   * @returns {PIXI.RenderTexture | null} The mask texture, or null if not found.
   */
  getMask(effectKey) {
    this._ensureMaskExists(effectKey);
    return this.masks.get(effectKey)?.texture || null;
  }
}

// lerp function moved to utils/ColorUtils.js

const systemStatus = new SystemStatusManager();

class TextureAutoLoader {
  static SUFFIX_MAP = {
    specular: "_Specular",
    ambient: "_Ambient",
    iridescence: "_Iridescence",
    groundGlow: "_GroundGlow",
    heat: "_Heat",
    fire: "_Fire",
    sparks: "_Sparks",
    dust: "_Dust",
    outdoors: "_Outdoors",
    canopy: "_Canopy",
    structural: "_Structural",
    prism: "_Prism",
    water: "_Water",
    caustics: "_Caustics",
    shoreline: "_Shoreline",
    steam: "_Steam",
  };

  // Cache for FilePicker.browse results to avoid redundant network requests
  // Key: directory path, Value: array of file paths
  static _directoryCache = new Map();
  
  // Cache statistics for performance monitoring
  static _cacheStats = { hits: 0, misses: 0 };

  /**
   * Clears the directory cache. Should be called when the scene changes
   * or when file system changes are expected.
   */
  static clearDirectoryCache() {
    TextureAutoLoader._directoryCache.clear();
    TextureAutoLoader._cacheStats = { hits: 0, misses: 0 };
  }
  
  /**
   * Gets cache statistics for performance monitoring.
   * @returns {Object} Object with hits and misses counts
   */
  static getCacheStats() {
    return { ...TextureAutoLoader._cacheStats };
  }

  async discoverAllTargets() {
    // Clear cache at the start of discovery to ensure fresh results for the current scene
    TextureAutoLoader.clearDirectoryCache();
    
    const results = {
      background: null,
      tiles: new Map(),
    };
    const backgroundTarget = await this._processSceneBackground();
    if (backgroundTarget) {
      results.background = backgroundTarget;
    }
    for (const tile of canvas.tiles.placeables) {
      const tileTarget = await this._processTile(tile);
      if (tileTarget) {
        results.tiles.set(tile.id, tileTarget);
      }
    }
    
    // Log cache performance statistics
    const stats = TextureAutoLoader.getCacheStats();
    const totalRequests = stats.hits + stats.misses;
    if (totalRequests > 0) {
      const hitRate = ((stats.hits / totalRequests) * 100).toFixed(1);
      // console.log(
      //   `Map Shine | Directory Cache Performance: ${stats.hits} hits, ${stats.misses} misses ` +
      //   `(${hitRate}% hit rate, avoided ${stats.hits} redundant network requests)`
      // );
    }
    
    // console.log("MapShine | Full Texture Discovery Results:", results);
    return results;
  }

  async _processSceneBackground() {
    const bgSrc = canvas.scene?.background.src;
    if (!bgSrc) {
      // No background texture - this is normal for some scenes
      return null;
    }
    const targetData = await this._findSuffixesForBaseTexture(bgSrc);

    targetData.baseTexturePath = bgSrc;
    targetData.rect = canvas.scene.dimensions.sceneRect;
    return targetData;
  }

  async _processTile(tile) {
    const tileSrc = tile.document.texture.src;
    if (!tileSrc) return null;

    const suffixData = await this._findSuffixesForBaseTexture(tileSrc);
    const hasEffectMap = Object.values(suffixData).some(
      (path) => path && typeof path === "string"
    );

    if (hasEffectMap) {
      return {
        tile,
        baseTexturePath: tileSrc,
        rect: {
          x: tile.document.x,
          y: tile.document.y,
          width: tile.document.width,
          height: tile.document.height,
          rotation: tile.document.rotation * (Math.PI / 180),
        },
        ...suffixData,
      };
    }
    return null;
  }

  async _findSuffixesForBaseTexture(baseTexturePath) {
    const discoveredPaths = {};
    Object.keys(TextureAutoLoader.SUFFIX_MAP).forEach(
      (key) => (discoveredPaths[key] = null)
    );

    // --- DIAGNOSTIC LOGGING ---
    const isWaterTile = baseTexturePath.toLowerCase().includes("water");
    // if (isWaterTile) {
    //   console.log(
    //     `--- Map Shine | DIAGNOSTIC: Auto-discovery for water-related tile ---`
    //   );
    //   console.log(`Base Texture Path: ${baseTexturePath}`);
    // }

    const lastSlash = baseTexturePath.lastIndexOf("/");
    if (lastSlash === -1) return discoveredPaths;

    const directoryPath = baseTexturePath.substring(0, lastSlash);
    const filename = baseTexturePath.substring(lastSlash + 1);

    let decodedFilename;
    try {
      decodedFilename = decodeURI(filename);
    } catch {
      decodedFilename = filename;
    }

    const lastDot = decodedFilename.lastIndexOf(".");
    if (lastDot === -1) return discoveredPaths;

    const baseName = decodedFilename.substring(0, lastDot);
    const extension = decodedFilename.substring(lastDot);

    // if (isWaterTile) {
    //   console.log(`Parsed Directory: ${directoryPath}`);
    //   console.log(`Parsed Base Name: ${baseName}`);
    //   console.log(`Parsed Extension: ${extension}`);
    // }

    if (!baseName || !directoryPath) return discoveredPaths;

    // Check cache first before making network request
    let filesInDir = TextureAutoLoader._directoryCache.get(directoryPath);
    
    if (!filesInDir) {
      // Cache miss - fetch from file system and cache the result
      TextureAutoLoader._cacheStats.misses++;
      try {
        const source = game.settings.get("core", "noCanvas") ? "public" : "data";
        filesInDir = (
          await foundry.applications.apps.FilePicker.implementation.browse(
            source,
            directoryPath
          )
        ).files;
        
        // Store in cache for future lookups
        TextureAutoLoader._directoryCache.set(directoryPath, filesInDir);
        
        // if (isWaterTile) {
        //   console.log(`Files found in directory (CACHE MISS):`, filesInDir);
        // }
      } catch {
        // Failed to browse directory
        return discoveredPaths;
      }
    } else {
      // Cache hit - using cached directory listing
      TextureAutoLoader._cacheStats.hits++;
      // if (isWaterTile) {
      //   console.log(`Files found in directory (CACHE HIT):`, filesInDir);
      // }
    }

    for (const [key, suffix] of Object.entries(TextureAutoLoader.SUFFIX_MAP)) {
      const expectedFilename = `${baseName}${suffix}${extension}`;

      // --- DIAGNOSTIC LOGGING for the shoreline ---
      // if (isWaterTile && key === "shoreline") {
      //   console.log(`Searching for key '${key}' with suffix '${suffix}'`);
      //   console.log(`Constructed Expected Filename: ${expectedFilename}`);
      // }

      const foundFile = filesInDir.find((fullPath) => {
        const fNameOnly = fullPath.substring(fullPath.lastIndexOf("/") + 1);
        let decodedFNameOnly;
        try {
          decodedFNameOnly = decodeURI(fNameOnly);
        } catch {
          decodedFNameOnly = fNameOnly;
        }
        return (
          decodedFNameOnly.toLowerCase() === expectedFilename.toLowerCase()
        );
      });

      if (foundFile) {
        // if (isWaterTile && key === "shoreline") {
        //   console.log(`SUCCESS: Found matching file path: ${foundFile}`);
        // }
        discoveredPaths[key] = foundFile;
      } else {
        // if (isWaterTile && key === "shoreline") {
        //   console.log(`FAILURE: No match found for '${expectedFilename}'.`);
        // }
      }
    }
    // if (isWaterTile) console.log(`--- END DIAGNOSTIC ---`);
    return discoveredPaths;
  }
}

class NoiseTextureManager {
  constructor(renderer, configPath, isWorldSpace = false) {
    this.configPath = configPath;
    this.isWorldSpace = isWorldSpace;
    this._needsUpdate = true; // A flag to force an update after config changes or pans.

    const screen = renderer.screen;

    this.renderTexture = PIXI.RenderTexture.create({
      width: screen.width,
      height: screen.height,
      scaleMode: PIXI.SCALE_MODES.LINEAR,
    });
    this.renderTexture.baseTexture.wrapMode = PIXI.WRAP_MODES.CLAMP;
    this.sourceSprite = new PIXI.Sprite(PIXI.Texture.WHITE);
    this.sourceSprite.width = screen.width;
    this.sourceSprite.height = screen.height;
    // START OF MODIFICATION
    this.filter = new NoisePatternFilter({
      u_isWorldSpace: this.isWorldSpace,
      u_resolution: [screen.width, screen.height], // Pass initial screen resolution here
    });
    this.sourceSprite.filters = [this.filter];
    // END OF MODIFICATION

    // If this is a world-space noise, it must re-render on pan.
    if (this.isWorldSpace) {
      this._onPanBound = this.requestUpdate.bind(this);
      if (!game.modules.get("libwrapper")?.active) {
        Hooks.on("canvasPan", this._onPanBound);
      }
    }
  }

  requestUpdate() {
    this._needsUpdate = true;
  }

  resize(renderer) {
    if (!this.renderTexture || !this.sourceSprite) return;
    const screen = renderer.screen;
    this.renderTexture.resize(screen.width, screen.height, true);
    this.sourceSprite.width = screen.width;
    this.sourceSprite.height = screen.height;
    if (this.filter) {
      this.filter.uniforms.u_resolution = [screen.width, screen.height];
    }
    this._needsUpdate = true;
  }

  updateFromConfig(config) {
    const nConfig = foundry.utils.getProperty(config, this.configPath);
    if (!nConfig || typeof nConfig !== "object") {
      if (this.filter) this.filter.enabled = false;
      return;
    }

    if (!this.filter) return;
    this.filter.enabled = true;

    // Define scaling factors based on the effect path to normalize UI values.
    const SCALING_FACTORS = {
      "canopy.distortion": { speed: 0.01, evolution: 0.01 },
      "prism.distortionNoise": { speed: 0.1, evolution: 0.1 },
      "structuralShadows.intensityNoise": { speed: 0.1, evolution: 0.1 },
      "iridescence.noise": { speed: 0.01, evolution: 0.01 },
    };
    const factors = SCALING_FACTORS[this.configPath] || {
      speed: 1.0,
      evolution: 1.0,
    };

    const u = this.filter.uniforms;
    u.u_speed = (nConfig["speed"] ?? 0.0) * (factors.speed ?? 1.0);
    u.u_scale = nConfig["scale"] ?? 1.0;
    u.u_threshold = nConfig["threshold"] ?? 0.5;
    u.u_brightness = nConfig["brightness"] ?? 1.0;
    u.u_contrast = nConfig["contrast"] ?? 1.0;
    u.u_softness = nConfig["softness"] ?? 0.0;
    u.u_evolution = (nConfig["evolution"] ?? 0.0) * (factors.evolution ?? 1.0);

    this.requestUpdate();
  }

  update(deltaTime, renderer) {
    if (!this.filter || !this.filter.enabled) return;

    const timeFactor = game.mapShine.timeControl.timeFactor ?? 1.0;
    const nConfig = foundry.utils.getProperty(
      game.mapShine.profileManager.activeConfig,
      this.configPath
    );
    const isAnimated =
      nConfig &&
      ((nConfig["speed"] ?? 0) * timeFactor !== 0 ||
        (nConfig["evolution"] ?? 0) * timeFactor !== 0);

    if (!this._needsUpdate && !isAnimated) return;

    this.filter.uniforms.uTime += deltaTime * timeFactor;

    // Get all necessary coordinate data from the centralized manager.
    if (this.isWorldSpace) {
      Object.assign(
        this.filter.uniforms,
        CoordinateManager.getShaderUniforms()
      );
    } else {
      // Screen-space filters only need resolution.
      this.filter.uniforms.uViewSize = [
        CoordinateManager.screenDimensions.width,
        CoordinateManager.screenDimensions.height,
      ];
    }

    renderer.render(this.sourceSprite, {
      renderTexture: this.renderTexture,
      clear: true,
    });
    this._needsUpdate = false;
  }

  getTexture() {
    return this.renderTexture;
  }

  destroy() {
    if (this.isWorldSpace && this._onPanBound) {
      Hooks.off("canvasPan", this._onPanBound);
    }

    this.filter?.destroy();
    this.sourceSprite?.destroy();
    this.renderTexture?.destroy(true);
  }
}

class DynamicTokenMaskManager {
  constructor(canvas) {
    this.canvas = canvas;
    if (!this.canvas?.app?.renderer) {
      console.error(
        "DynamicTokenMaskManager | Cannot initialize without a canvas renderer."
      );
      return;
    }
    console.log("DynamicTokenMaskManager | Initializing with sprite pooling.");

    const screen = CoordinateManager.getScreenDimensions();

    // PERFORMANCE OPTIMIZATION: Use half-resolution for token mask
    // Soft-edged effects don't need full resolution
    const halfWidth = Math.floor(screen.width / 2);
    const halfHeight = Math.floor(screen.height / 2);

    this.renderTexture = PIXI.RenderTexture.create({
      width: halfWidth,
      height: halfHeight,
    });

    this.tokenContainer = new PIXI.Container();
    this.tokenSprites = new Map();
    this._needsUpdate = true;
    this._destroyed = false;

    this._frameCount = 0;
    this.updateFrequency = 30;

    this._boundOnTokenChange = this._requestUpdate.bind(this);

    Hooks.on("createToken", this._boundOnTokenChange);
    Hooks.on("deleteToken", this._boundOnTokenChange);
    Hooks.on("canvasPan", this._boundOnTokenChange);

    this._boundOnAnimate = () => {
      if (this._destroyed || !this.canvas?.stage?.transform) return;

      this._frameCount++;
      const isNthFrame = this._frameCount % this.updateFrequency === 0;

      if (this._needsUpdate || isNthFrame) {
        this.renderMask();
        this._needsUpdate = false;
      }
    };
    this.canvas.app.ticker.add(this._boundOnAnimate);

    // Register resize handler
    this._boundOnResize = this._onResize.bind(this);
    window.addEventListener("resize", this._boundOnResize);

    this.renderMask();
  }

  _requestUpdate() {
    this._needsUpdate = true;
  }

  renderMask() {
    if (
      this._destroyed ||
      !this.tokenContainer ||
      !this.canvas?.tokens?.placeables
    )
      return;
    const renderer = this.canvas.app.renderer;

    const currentTokenIds = new Set();

    for (const token of this.canvas.tokens.placeables) {
      if (!token.visible || !token.texture?.valid || token.document.hidden) {
        continue;
      }
      currentTokenIds.add(token.id);

      let sprite = this.tokenSprites.get(token.id);

      if (!sprite) {
        sprite = new PIXI.Sprite(token.texture);
        sprite.tint = 0xffffff;
        this.tokenSprites.set(token.id, sprite);
        this.tokenContainer.addChild(sprite);
      }

      if (sprite.texture !== token.texture) {
        sprite.texture = token.texture;
      }

      const anchorX = token.document.texture.anchorX ?? 0.5;
      const anchorY = token.document.texture.anchorY ?? 0.5;
      sprite.anchor.set(anchorX, anchorY);
      sprite.position.set(token.center.x, token.center.y);
      sprite.width = token.w;
      sprite.height = token.h;
      sprite.rotation = Math.toRadians(token.document.rotation);
    }

    for (const [tokenId, sprite] of this.tokenSprites.entries()) {
      if (!currentTokenIds.has(tokenId)) {
        sprite.destroy();
        this.tokenSprites.delete(tokenId);
      }
    }

    if (!this.canvas?.stage?.transform) return;

    renderer.render(this.tokenContainer, {
      renderTexture: this.renderTexture,
      transform: this.canvas.stage.transform.worldTransform,
      clear: true,
    });
  }

  getMaskTexture() {
    return this.renderTexture;
  }

  _onResize() {
    if (this._destroyed) return;
    const screen = CoordinateManager.getScreenDimensions();
    const halfWidth = Math.floor(screen.width / 2);
    const halfHeight = Math.floor(screen.height / 2);

    this.renderTexture?.resize(halfWidth, halfHeight);
    this._needsUpdate = true;
  }

  destroy() {
    if (this._destroyed) return;
    this._destroyed = true;
    console.log("DynamicTokenMaskManager | Destroying.");
    Hooks.off("createToken", this._boundOnTokenChange);
    Hooks.off("deleteToken", this._boundOnTokenChange);
    Hooks.off("canvasPan", this._boundOnTokenChange);
    this.canvas.app.ticker.remove(this._boundOnAnimate);
    window.removeEventListener("resize", this._boundOnResize);

    this.renderTexture?.destroy(true);
    for (const sprite of this.tokenSprites.values()) {
      sprite.destroy();
    }
    this.tokenSprites.clear();
    this.tokenContainer?.destroy({
      children: true,
    });
    this.renderTexture = null;
    this.tokenContainer = null;
  }
}

class CompositeMaskGenerator {
  /**
   * Creates a new texture by blending two source textures with a MULTIPLY effect.
   * @param {string} baseTexturePath - The path to the first texture (e.g., _Dust).
   * @param {string} overlayTexturePath - The path to the second texture (e.g., _Structural).
   * @param {PIXI.Rectangle} rect - The world-space rectangle defining the target area.
   * @returns {Promise<PIXI.RenderTexture|null>} A promise that resolves to the new composite texture, or null on failure.
   */
  static async generate(baseTexturePath, overlayTexturePath, rect) {
    const renderer = canvas.app?.renderer;
    if (!renderer || !rect || !baseTexturePath || !overlayTexturePath)
      return null;

    try {
      const [baseTex, overlayTex] = await Promise.all([
        TextureLoader.loadTexture(baseTexturePath),
        TextureLoader.loadTexture(overlayTexturePath),
      ]);

      const container = new PIXI.Container();

      const baseSprite = new PIXI.Sprite(baseTex);

      const overlaySprite = new PIXI.Sprite(overlayTex);

      // Set sprite properties to match the target tile/background
      baseSprite.width = overlaySprite.width = rect.width;
      baseSprite.height = overlaySprite.height = rect.height;
      baseSprite.position.set(rect.x, rect.y);
      overlaySprite.position.set(rect.x, rect.y);

      // Set the blend mode to MULTIPLY to get the intersection
      overlaySprite.blendMode = PIXI.BLEND_MODES.MULTIPLY;

      container.addChild(baseSprite, overlaySprite);

      // Create a render texture to capture the result

      const renderTexture = PIXI.RenderTexture.create({
        width: renderer.screen.width,
        height: renderer.screen.height,
      });

      // Render the container with the world transform to the screen-sized texture
      renderer.render(container, {
        renderTexture: renderTexture,
        transform: canvas.stage.transform.worldTransform,
        clear: true,
      });

      // Clean up the temporary PIXI objects
      container.destroy({
        children: true,
      });

      return renderTexture;
    } catch (error) {
      console.error(
        `Map Shine | Failed to generate composite mask from "${baseTexturePath}" and "${overlayTexturePath}"`,
        error
      );
      return null;
    }
  }
}

// =================================================================================
// SECTION 7: LIGHTNING SYSTEM
// =================================================================================
// Description: Complete lightning effect system including effects, manager,
//              occlusion filter, and canvas layer. Provides animated lightning
//              bolts with realistic branching and wall occlusion.
// ---------------------------------------------------------------------------------
// LightningEffect, LightningManager, and LightningOcclusionFilter classes removed.
// Lightning functionality has been simplified and moved to LightningLayer.

// =================================================================================
// SECTION 8: PARTICLE SYSTEMS
// =================================================================================
// Description: Complete particle system including definitions, emitter configurations,
//              controllers, behaviors, managers, and canvas layers. Handles fire,
//              sparks, dust, steam, flies, and foam particle effects.
// ---------------------------------------------------------------------------------

/***************************************************************************************
 *
 *                              PARTICLE SYSTEM BUG REPORT & LESSONS
 *
 *  ROOT CAUSE OF PROPERTYLIST BUG:
 *  A bug was identified within the external `particle-emitter.min.js` library in the
 *  `PropertyNode.createList()` method. This method has an optimization that fails when
 *  it is provided a property list with exactly two entries that have identical values
 *  (e.g., `list: [{value: 1, time: 0}, {value: 1, time: 1}]`).
 *
 *  BUG BEHAVIOR:
 *  Instead of creating a two-node linked list, the optimization creates a single-node list.
 *  The system then incorrectly selects a complex interpolation function (`intValueComplex` or
 *  `intColorComplex`) which is not designed to handle a single-node list. This function
 *  crashes when it attempts to access `node.next.time`, as `node.next` is null,
 *  resulting in the observed TypeError.
 *
 *  SOLUTION:
 *  The affected `build...EmitterConfig` functions were refactored. The solution has two parts:
 *
 *  1.  It now checks if the start and end values for a property (e.g., scale, color) are
 *      identical. If they are, it uses the appropriate `Static` behavior (e.g., `scaleStatic`),
 *      which completely bypasses the buggy `PropertyList` logic.
 *
 *  2.  If the values differ, it uses the dynamic behavior but provides the configuration in the
 *      legacy `{start, end}` format. The library correctly handles this format without triggering
 *      the bug.
 *
 *  This approach makes our code resilient to the underlying library issue.
 *
 *  ---
 *
 *  EMITTER STATE CORRUPTION BUG (LESSON LEARNED):
 *  During the development of the "Pressurised Steam" effect, a persistent issue was
 *  encountered where dynamically changing an emitter's rotation after initialization
 *  would cause it to permanently stop emitting particles.
 *
 *  BUG BEHAVIOR:
 *  Calling `emitter.rotate()` or manually setting `emitter.rotation` inside an update
 *  loop or on a timer consistently resulted in the emitter entering a non-functional state.
 *  This occurred even when using the library's intended `emitter.emit = true/false`
 *  mechanism for emission control.
 *
 *  ROOT CAUSE & SOLUTION:
 *  The root cause is likely an instability in the `pixi-particles` library where modifying
 *  the emitter's core transform properties (rotation, spawn position) after particles
 *  have already been emitted leads to an unrecoverable internal state corruption.
 *
 *  The definitive solution is to **AVOID MODIFYING THE EMITTER'S ROTATION POST-INITIALIZATION**.
 *  Instead of setting `emitter.rotation` to change the direction of a burst, all movement
 *  logic should be encapsulated within a custom behavior that operates at the particle level.
 *
 *  CORRECT IMPLEMENTATION PATTERN:
 *  1.  **Static Emitter:** Configure the emitter with no built-in movement behaviors (e.g., remove `moveSpeed`).
 *  2.  **Custom Behavior (`initParticles`):** For each new particle, calculate its initial
 *      velocity vector based on the desired (and potentially randomized) angle and speed. Store
 *      this velocity on the particle object itself (e.g., `particle.velocity = new PIXI.Point(...)`).
 *  3.  **Custom Behavior (`updateParticle`):** On each frame, update the particle's position
 *      manually using its stored velocity and the frame's delta time (`particle.position.x += particle.velocity.x * deltaSec`).
 *      This method also allows for implementing custom physics like air drag by modifying the
 *      velocity over the particle's lifetime.
 *
 ***************************************************************************************/

/*

    Below are the variables/options that are required when creating particles. Be sure to conform to these requirements.


    {
      // Minimum and maximum lifetime of a particle in seconds.
      "lifetime": {
        "min": number,
        "max": number
      },
      // The time in seconds between particle spawns.
      "frequency": number,
      // The probability (0-1) that a particle will be spawned.
      "spawnChance": number,
      // The number of particles created at each spawn emission.
      "particlesPerWave": number,
      // The lifetime of the emitter in seconds (-1 for infinite).
      "emitterLifetime": number,
      // The maximum number of particles that can exist at one time.
      "maxParticles": number,
      // The starting position of the emitter.
      "pos": {
        "x": number,
        "y": number
      },
      // An array of behavior objects that define particle appearance and movement.
      "behaviors": [
        {
          "type": string,
          "config": object
        }
      ]
    } */

